package com.citacloud.springboot.contacloud.app.services;

import com.citacloud.springboot.contacloud.app.dto.*;import com.citacloud.springboot.contacloud.app.models.*;import com.citacloud.springboot.contacloud.app.repositories.*;import com.citacloud.springboot.contacloud.app.security.*;
import org.springframework.data.domain.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;import java.time.LocalDate;import java.util.*;

@Service
public class TransferenciaInventarioService{
 private static final Set<Integer>SIZES=Set.of(10,25,50,100);
 private final TransferenciaInventarioRepository transfers;private final LineaTransferenciaInventarioRepository lines;
 private final AlmacenRepository warehouses;private final SucursalRepository branches;private final ProductRepository products;
 private final InventoryMovementRepository movementRepository;private final InventoryMovementService movementService;
 private final TransferenciaInventarioNumeroService numbers;private final AuditoriaService audit;
 public TransferenciaInventarioService(TransferenciaInventarioRepository transfers,LineaTransferenciaInventarioRepository lines,
  AlmacenRepository warehouses,SucursalRepository branches,ProductRepository products,InventoryMovementRepository movementRepository,
  InventoryMovementService movementService,TransferenciaInventarioNumeroService numbers,AuditoriaService audit){this.transfers=transfers;this.lines=lines;this.warehouses=warehouses;this.branches=branches;this.products=products;this.movementRepository=movementRepository;this.movementService=movementService;this.numbers=numbers;this.audit=audit;}

 @Transactional(readOnly=true) @PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and hasAuthority('inventario_transferencias.ver')")
 public Page<TransferenciaInventarioDto> buscar(String q,LocalDate desde,LocalDate hasta,EstadoTransferenciaInventario estado,
  UUID sucursalOrigen,UUID almacenOrigen,UUID sucursalDestino,UUID almacenDestino,int page,int size){if(page<0||!SIZES.contains(size))throw new ReglaNegocioException("Paginación inválida.");if(desde!=null&&hasta!=null&&desde.isAfter(hasta))throw new ReglaNegocioException("La fecha inicial no puede ser posterior a la fecha final.");var p=TenantContext.principalActual();UUID e=EmpresaContext.requerirEmpresaId();validarSucursalOpcional(sucursalOrigen);validarSucursalOpcional(sucursalDestino);return transfers.buscar(p.tenantId(),e,texto(q).toLowerCase(Locale.ROOT),desde,hasta,estado,sucursalOrigen,almacenOrigen,sucursalDestino,almacenDestino,PageRequest.of(page,size,Sort.by(Sort.Direction.DESC,"fecha").and(Sort.by(Sort.Direction.DESC,"creadaEn")))).map(this::dtoBasico);}

 @Transactional(readOnly=true) @PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and hasAuthority('inventario_transferencias.ver')")
 public TransferenciaInventarioDto obtener(UUID id){return dtoCompleto(segura(id,false));}

 @Transactional(readOnly=true) @PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and hasAuthority('inventario_transferencias.ver')")
 public TransferenciaInventarioCatalogosDto catalogos(UUID almacenOrigenId){var p=TenantContext.principalActual();UUID e=EmpresaContext.requerirEmpresaId();var ws=warehouses.findAllByTenantIdAndEmpresaIdAndActivoTrueOrderByNombre(p.tenantId(),e).stream().filter(w->EmpresaContext.permiteSucursal(w.getSucursalId())).toList();var bs=branches.findAllByEmpresaIdAndActivoTrueOrderByNombre(e).stream().filter(b->EmpresaContext.permiteSucursal(b.getId())).map(b->new TransferenciaInventarioCatalogosDto.Sucursal(b.getId(),b.getNombre())).toList();var ps=products.findAllByTenantIdAndEmpresaIdAndActivoTrueAndControlaExistenciaTrueOrderByNombre(p.tenantId(),e).stream().filter(x->x.getTipo()==TipoProducto.PRODUCT).map(x->new TransferenciaInventarioCatalogosDto.Producto(x.getId(),x.getCodigo(),x.getNombre(),x.getUnidadMedidaId(),x.getUnidadMedida()==null?"Unidad":x.getUnidadMedida().getNombre(),almacenOrigenId==null?BigDecimal.ZERO:movementRepository.saldo(p.tenantId(),e,almacenOrigenId,x.getId()),x.isPermiteExistenciaNegativa())).toList();return new TransferenciaInventarioCatalogosDto(bs,ws.stream().map(w->new TransferenciaInventarioCatalogosDto.Almacen(w.getId(),w.getSucursalId(),w.getNombre(),w.getSucursal().getNombre())).toList(),ps);}

 @Transactional @PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and hasAuthority('inventario_transferencias.crear')")
 public TransferenciaInventarioDto crear(TransferenciaInventarioInput input){var v=validar(input);var p=TenantContext.principalActual();UUID e=EmpresaContext.requerirEmpresaId();TransferenciaInventario t=new TransferenciaInventario(p.tenantId(),e,numbers.siguiente(p.tenantId(),e),v.fecha(),v.tipo(),v.origen().getId(),v.destino().getId(),v.referencia(),v.notas(),p.usuarioId());t.asignarAlmacenes(v.origen(),v.destino());t=transfers.saveAndFlush(t);guardarLineas(t,v.productos());audit.registrar("INVENTORY_TRANSFER_CREATED","INVENTORY_TRANSFER",t.getId(),detalle(t));return dtoCompleto(t);}

 @Transactional @PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and hasAuthority('inventario_transferencias.editar')")
 public TransferenciaInventarioDto actualizar(UUID id,TransferenciaInventarioInput input){var t=segura(id,true);if(t.getEstado()!=EstadoTransferenciaInventario.DRAFT)throw new ReglaNegocioException("Solo se puede editar una transferencia en borrador.");if(input.version()!=null&&input.version()!=t.getVersion())throw new ReglaNegocioException("La transferencia fue modificada por otro usuario. Actualiza la pantalla.");var v=validar(input);var p=TenantContext.principalActual();t.actualizar(v.fecha(),v.tipo(),v.origen().getId(),v.destino().getId(),v.referencia(),v.notas(),p.usuarioId());t.asignarAlmacenes(v.origen(),v.destino());lines.deleteAllByTransferenciaId(t.getId());lines.flush();guardarLineas(t,v.productos());transfers.saveAndFlush(t);audit.registrar("INVENTORY_TRANSFER_UPDATED","INVENTORY_TRANSFER",t.getId(),detalle(t));return dtoCompleto(t);}

 @Transactional @PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and hasAuthority('inventario_transferencias.despachar')")
 public TransferenciaInventarioDto confirmarDirecta(UUID id){var t=segura(id,true);if(t.getEstado()==EstadoTransferenciaInventario.RECEIVED)return dtoCompleto(t);if(t.getTipo()!=TipoTransferenciaInventario.DIRECT)throw new ReglaNegocioException("Esta transferencia requiere despacho y recepción.");List<LineaTransferenciaInventario> ls=lines.findAllByTransferenciaIdOrderByOrden(t.getId());var p=TenantContext.principalActual();validarDisponibilidad(t,ls);t.capturarContextoHistorico(t.getOrigen(),t.getDestino());for(var l:ls){movementService.transferir(t,l,t.getAlmacenOrigenId(),"OUT","TRANSFER_DIRECT_OUT",p.usuarioId());movementService.transferir(t,l,t.getAlmacenDestinoId(),"IN","TRANSFER_DIRECT_IN",p.usuarioId());l.recibirCompleta();}t.confirmarDirecta(p.usuarioId(),p.nombre());audit.registrar("INVENTORY_TRANSFER_CONFIRMED","INVENTORY_TRANSFER",t.getId(),detalle(t));return dtoCompleto(t);}

 @Transactional @PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and hasAuthority('inventario_transferencias.despachar')")
 public TransferenciaInventarioDto despachar(UUID id){var t=segura(id,true);if(t.getEstado()==EstadoTransferenciaInventario.IN_TRANSIT)return dtoCompleto(t);if(t.getTipo()!=TipoTransferenciaInventario.IN_TRANSIT)throw new ReglaNegocioException("La transferencia directa debe confirmarse.");List<LineaTransferenciaInventario> ls=lines.findAllByTransferenciaIdOrderByOrden(t.getId());validarDisponibilidad(t,ls);Almacen transit=warehouses.findFirstByTenantIdAndEmpresaIdAndAdministradoSistemaTrueAndTipo(t.getTenantId(),t.getEmpresaId(),TipoAlmacen.TRANSITO).orElseThrow(()->new ReglaNegocioException("No existe el almacén técnico de tránsito para la empresa."));var p=TenantContext.principalActual();t.capturarContextoHistorico(t.getOrigen(),t.getDestino());for(var l:ls){movementService.transferir(t,l,t.getAlmacenOrigenId(),"OUT","TRANSFER_DISPATCH_OUT",p.usuarioId());movementService.transferir(t,l,transit.getId(),"IN","TRANSFER_TRANSIT_IN",p.usuarioId());}t.despachar(transit.getId(),p.usuarioId(),p.nombre());audit.registrar("INVENTORY_TRANSFER_DISPATCHED","INVENTORY_TRANSFER",t.getId(),detalle(t));return dtoCompleto(t);}

 @Transactional @PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and hasAuthority('inventario_transferencias.recibir')")
 public TransferenciaInventarioDto recibir(UUID id){var t=segura(id,true);if(t.getEstado()==EstadoTransferenciaInventario.RECEIVED)return dtoCompleto(t);if(t.getEstado()!=EstadoTransferenciaInventario.IN_TRANSIT)throw new ReglaNegocioException("Solo se puede recibir una transferencia en tránsito.");var p=TenantContext.principalActual();for(var l:lines.findAllByTransferenciaIdOrderByOrden(t.getId())){movementService.transferir(t,l,t.getAlmacenTransitoId(),"OUT","TRANSFER_TRANSIT_OUT",p.usuarioId());movementService.transferir(t,l,t.getAlmacenDestinoId(),"IN","TRANSFER_RECEIPT_IN",p.usuarioId());l.recibirCompleta();}t.recibir(p.usuarioId(),p.nombre());audit.registrar("INVENTORY_TRANSFER_RECEIVED","INVENTORY_TRANSFER",t.getId(),detalle(t));return dtoCompleto(t);}

 @Transactional @PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and hasAuthority('inventario_transferencias.cancelar')")
 public TransferenciaInventarioDto cancelar(UUID id,String motivo){var t=segura(id,true);if(t.getEstado()==EstadoTransferenciaInventario.CANCELLED)return dtoCompleto(t);if(texto(motivo).isBlank())throw new ReglaNegocioException("El motivo de cancelación es obligatorio.");t.cancelar(motivo.trim(),TenantContext.principalActual().usuarioId());audit.registrar("INVENTORY_TRANSFER_CANCELLED","INVENTORY_TRANSFER",t.getId(),detalle(t));return dtoCompleto(t);}

 @Transactional @PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and hasAuthority('inventario_transferencias.despachar') and (hasAuthority('inventario_transferencias.crear') or hasAuthority('inventario_transferencias.editar'))")
 public TransferenciaInventarioDto guardarYProcesar(UUID id,TransferenciaInventarioInput input){Set<String> permisos=TenantContext.principalActual().permisos();if(id==null&&!permisos.contains("inventario_transferencias.crear"))throw new ReglaNegocioException("No tienes permiso para crear transferencias.");if(id!=null&&!permisos.contains("inventario_transferencias.editar"))throw new ReglaNegocioException("No tienes permiso para editar transferencias.");TransferenciaInventarioDto guardada=id==null?crear(input):actualizar(id,input);return input.tipo()==TipoTransferenciaInventario.DIRECT?confirmarDirecta(guardada.id()):despachar(guardada.id());}

 private Validado validar(TransferenciaInventarioInput i){if(i==null||i.fecha()==null)throw new ReglaNegocioException("La fecha es obligatoria.");if(i.tipo()==null)throw new ReglaNegocioException("El tipo de transferencia es obligatorio.");Almacen o=almacen(i.almacenOrigenId()),d=almacen(i.almacenDestinoId());if(o.getId().equals(d.getId()))throw new ReglaNegocioException("El almacén de origen y el almacén de destino deben ser diferentes.");if(i.lineas()==null||i.lineas().isEmpty())throw new ReglaNegocioException("Agrega al menos un producto a la transferencia.");Set<String> unique=new HashSet<>();List<ProductoCantidad> ps=new ArrayList<>();for(var l:i.lineas()){if(l==null||l.productoId()==null)throw new ReglaNegocioException("Selecciona un producto.");if(l.cantidad()==null||l.cantidad().signum()<=0)throw new ReglaNegocioException("La cantidad debe ser mayor que cero.");Producto p=producto(l.productoId(),false);if(p.getTipo()!=TipoProducto.PRODUCT||!p.isControlaExistencia())throw new ReglaNegocioException("Solo se permiten productos con control de existencia.");if(l.unidadId()!=null&&!l.unidadId().equals(p.getUnidadMedidaId()))throw new ReglaNegocioException("La unidad seleccionada no corresponde al producto.");if(!unique.add(p.getId()+":"+p.getUnidadMedidaId()))throw new ReglaNegocioException("El producto ya fue agregado a la transferencia.");ps.add(new ProductoCantidad(p,l.cantidad()));}return new Validado(i.fecha(),i.tipo(),o,d,limpiar(i.referencia()),limpiar(i.notas()),ps);}
 private void validarDisponibilidad(TransferenciaInventario t,List<LineaTransferenciaInventario> ls){if(t.getEstado()!=EstadoTransferenciaInventario.DRAFT)throw new ReglaNegocioException("La transferencia ya fue procesada.");Map<UUID,Producto> bloqueados=new HashMap<>();ls.stream().map(LineaTransferenciaInventario::getProductoId).distinct().sorted(Comparator.comparing(UUID::toString)).forEach(id->bloqueados.put(id,producto(id,true)));for(var l:ls){Producto p=bloqueados.get(l.getProductoId());BigDecimal available=movementRepository.saldo(t.getTenantId(),t.getEmpresaId(),t.getAlmacenOrigenId(),p.getId());if(!p.isPermiteExistenciaNegativa()&&available.compareTo(l.getCantidadBase())<0)throw new ReglaNegocioException("Existencia insuficiente para "+p.getNombre()+". Disponible: "+available.stripTrailingZeros().toPlainString()+".");}}
 private void guardarLineas(TransferenciaInventario t,List<ProductoCantidad> ps){int n=1;for(var x:ps)lines.save(new LineaTransferenciaInventario(t.getId(),t.getTenantId(),t.getEmpresaId(),x.producto(),x.cantidad(),n++));}
 private TransferenciaInventario segura(UUID id,boolean lock){if(id==null)throw new RecursoNoEncontradoException("Transferencia no encontrada.");var p=TenantContext.principalActual();TransferenciaInventario t=(lock?transfers.bloquear(id,p.tenantId(),p.empresaId()):transfers.findByIdAndTenantIdAndEmpresaId(id,p.tenantId(),p.empresaId())).orElseThrow(()->new RecursoNoEncontradoException("Transferencia no encontrada."));if(!EmpresaContext.permiteSucursal(t.getOrigen().getSucursalId())||!EmpresaContext.permiteSucursal(t.getDestino().getSucursalId()))throw new ReglaNegocioException("No tienes acceso a las sucursales de esta transferencia.");return t;}
 private Almacen almacen(UUID id){var p=TenantContext.principalActual();Almacen w=warehouses.findByIdAndTenantIdAndEmpresaId(id,p.tenantId(),p.empresaId()).orElseThrow(()->new RecursoNoEncontradoException("Almacén no encontrado."));if(!w.isActivo()||w.isAdministradoSistema())throw new ReglaNegocioException("El almacén seleccionado no está disponible.");if(!EmpresaContext.permiteSucursal(w.getSucursalId()))throw new ReglaNegocioException("No tienes acceso a la sucursal del almacén.");return w;}
 private Producto producto(UUID id,boolean lock){var p=TenantContext.principalActual();return (lock?products.bloquear(id,p.tenantId(),p.empresaId()):products.findByIdAndTenantIdAndEmpresaId(id,p.tenantId(),p.empresaId())).orElseThrow(()->new RecursoNoEncontradoException("Producto no encontrado."));}
 private void validarSucursalOpcional(UUID id){if(id!=null&&(!EmpresaContext.permiteSucursal(id)||branches.findByIdAndEmpresaId(id,EmpresaContext.requerirEmpresaId()).isEmpty()))throw new ReglaNegocioException("No tienes acceso a la sucursal seleccionada.");}
 private TransferenciaInventarioDto dtoBasico(TransferenciaInventario t){return dto(t,List.of());}
 private TransferenciaInventarioDto dtoCompleto(TransferenciaInventario t){return dto(t,lines.findAllByTransferenciaIdOrderByOrden(t.getId()));}
 private static TransferenciaInventarioDto dto(TransferenciaInventario t,List<LineaTransferenciaInventario> ls){String ao=first(t.getAlmacenOrigenHistorico(),t.getOrigen().getNombre()),so=first(t.getSucursalOrigenHistorica(),t.getOrigen().getSucursal().getNombre()),ad=first(t.getAlmacenDestinoHistorico(),t.getDestino().getNombre()),sd=first(t.getSucursalDestinoHistorica(),t.getDestino().getSucursal().getNombre());return new TransferenciaInventarioDto(t.getId(),t.getNumero(),t.getFecha(),t.getTipo(),t.getAlmacenOrigenId(),ao,so,t.getAlmacenDestinoId(),ad,sd,t.getEstado(),t.getReferencia(),t.getNotas(),t.getDespachadaEn(),t.getDespachadaPorNombre(),t.getRecibidaEn(),t.getRecibidaPorNombre(),t.getCanceladaEn(),t.getMotivoCancelacion(),t.getVersion(),ls.stream().map(l->new TransferenciaInventarioDto.Linea(l.getId(),l.getProductoId(),l.getCodigoProducto(),l.getNombreProducto(),l.getDescripcion(),l.getUnidadId(),l.getUnidad(),l.getCantidadDespachada(),l.getCantidadRecibida(),l.getCantidadPendiente(),l.getDiferencia(),l.getMotivoDiferencia())).toList());}
 private static String texto(String v){return v==null?"":v.trim();}private static String limpiar(String v){String x=texto(v);return x.isEmpty()?null:x;}private static String first(String value,String fallback){return value==null||value.isBlank()?fallback:value;}private static String detalle(TransferenciaInventario t){return "{\"numero\":\""+t.getNumero()+"\",\"estado\":\""+t.getEstado()+"\"}";}
 private record ProductoCantidad(Producto producto,BigDecimal cantidad){} private record Validado(LocalDate fecha,TipoTransferenciaInventario tipo,Almacen origen,Almacen destino,String referencia,String notas,List<ProductoCantidad> productos){}
}
